ON CONFLICT (id) DO UPDATE SET
  path = EXCLUDED.path,
  full_path = EXCLUDED.full_path,
  depth = EXCLUDED.depth,
  remedy_count = EXCLUDED.remedy_count,
  cross_references = EXCLUDED.cross_references,
  updated_at = NOW();
